"status": "draft", "id": "ffc52aae-093c-57ce-a03c-f416683079f6"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "朱玫", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：朱玫。", "biography": null, "status": "draft", "id": "bb37d3e7-f348-51ea-bc68-8b4355399a19"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "赫连铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：赫连铎。", "biography": null, "status": "draft", "id": "b54a0fc9-ea29-5e0d-9d2a-f8fe5be8cda9"}, {"name": "白义诚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：白义诚。", "biography": null, "status": "draft", "id": "b8223a0e-2097-52c3-a1ec-aa2e75e0de84"}, {"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "杨守亮", "aliases": ["訾亮"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨守亮。", "biography": null, "status": "draft", "id": "794556be-c340-512f-923f-61f100db55df"}, {"name": "杨守信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨守信。", "biography": null, "status": "draft", "id": "3162cc98-31d1-5f1c-8d13-86cc7912a541"}, {"name": "郑綮", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：郑綮。", "biography": null, "status": "draft