INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "冯敬章邀击淮南军，朱延寿攻蕲未克", "start_year": 894, "end_year": 894, "time_original": "894年六月条；具体日未载", "dynasty": "唐", "description": "蕲州刺史冯敬章截击淮南军；朱延寿攻蕲州，没有攻下。", "phases": [], "location_name": "蕲州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3c05e928-b4cf-5580-b3ca-569907458241"}, {"title": "朝廷宣制授李溪同平章事", "start_year": 894, "end_year": 894, "time_original": "894年六月戊午", "dynasty": "唐", "description": "朝廷宣制，以翰林学士承旨、礼部尚书李溪为同平章事。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3d414c2c-fd1b-5212-bc0a-a57017ee950c"}, {"title": "刘崇鲁掠麻恸哭，向昭宗指控李溪", "start_year": 894, "end_year": 894, "time_original": "894年六月戊午；方宣制时", "dynasty": "唐", "description": "宣制时，水部郎中知制诰刘崇鲁出班取制书恸哭。昭宗问原因，刘指称李溪奸邪、依附杨复恭西门君遂得翰林职，没有宰相才能，恐危社稷。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ae1075df-1dfa-5ded-bc79-cfea164a3605"}, {"title": "李溪任相受阻，改太子少傅", "start_year": 894, "end_year": 894, "time_original": "宣制被阻后；确日未载", "dynasty": "唐", "description": "李溪任相最终受阻，改为太子少傅。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "354cab1b-c606-53de-a556-066ab4310237"}, {"title": "崔昭纬恐李溪分权，使刘崇鲁阻相", "start_year": 894, "end_year": 894, "time_original": "李溪拟任相时；背景具体日未载", "dynasty": "唐", "description": "《通鉴》叙崔昭纬怕李溪任相分去权力，因此使刘崇鲁阻止。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "379aebab-481f-5fec-a1aa-74f9ab3704f4"}, {"title": "李溪十表自讼，反驳并指控刘氏", "start_year": 894, "end_year": 894, "time_original": "任相受阻后；十表具体日期未载", "dynasty": "唐", "description": "李溪十次上表为自己辩解，斥刘崇鲁父符受赃事觉自杀，并指崇望与杨复恭深交、崇鲁曾拜田令孜和为朱玫作劝进表；他援礼制批评刘在殿上恸哭，请求治罪。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ddaf8fae-0e47-50d2-851c-e97c4245fb45"}, {"title": "诏停刘崇鲁现任官职", "start_year": 894, "end_year": 894, "time_original": "李溪上表后；确日未载", "dynasty": "唐", "description": "朝廷下诏停止刘崇鲁的现任官职。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fb50699a-11ba-5e47-8a41-759b1f49fba1"}, {"title": "李溪仍上表求诛窜，言辞激烈", "start_year": 894, "end_year": 894, "time_original": "停刘崇鲁见任后；确日未载", "dynasty": "唐", "description": "停刘崇鲁官以后，李溪继续上表，要求处死或流窜刘氏，奏表数千言，书叙其诟骂无所不至。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "46cba6b8-c73e-5d0c-b23e-503c6743d0f0"}, {"title": "李克用破吐谷浑，杀赫连铎擒白义诚", "start_year": 894, "end_year": 894, "time_original": "894年六月条；具体日未载", "dynasty": "唐", "description": "李克用大败吐谷浑，杀赫连铎，俘白义诚。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "03c86585-1641-5c3e-827a-fd93cf360b46"}, {"title": "李茂贞遣军攻取阆州", "start_year": 894, "end_year": 894, "time_original": "894年秋七月", "dynasty": "唐", "description": "李茂贞派军进攻阆州，将其攻下。", "phases": [], "location_name": "阆州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "866167d0-838c-5014-9ded-6f4baaf261d8"}, {"title": "杨复恭杨守亮杨守信率族党突围", "start_year": 894, "end_year": 894, "time_original": "894年七月阆州被攻时", "dynasty": "唐", "description": "杨复恭、杨守亮、杨守信带族党冲出包围逃走。", "phases": [], "location_name": "阆州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8c7ec8c4-0e42-5fda-a07a-2bba75ee01db"}, {"title": "郑綮累表避位，太子少保致仕", "start_year": 894, "end_year": 894, "time_original": "894年七月条；具体日未载", "dynasty": "唐", "description": "礼部侍郎、同平章事郑綮自觉不合众望，多次上表辞位，朝廷诏以太子少保致仕。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "807b87ef-ddf2-597d-991f-9f787da86cde"}, {"title": "徐彦若复为中书侍郎兼吏部尚书同平章事", "start_year": 894, "end_year": 894, "time_original": "894年七月条；具体日未载", "dynasty": "唐", "description": "御史大夫徐彦若被任为中书侍郎兼吏部尚书、同平章事。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "97dd4cc7-bfee-574f-9906-23be0f676e61"}, {"title": "绵州刺史杨守厚卒", "start_year": 894, "end_year": 894, "time_original": "894年七月条；具体日未载", "dynasty": "唐", "description": "绵州刺史杨守厚去世。", "phases": [], "location_name": "绵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f7f7ad15-d674-5595-89af-04a4626c312e"}, {"title": "常再荣举绵州降王建", "start_year": 894, "end_year": 894, "time_original": "杨守厚卒后；具体日未载", "dynasty": "唐", "description": "杨守厚部将常再荣带城归降王建。", "phases": [], "location_name": "绵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "654da383-65e0-5d20-a291-7a04d95736f2"}, {"title": "杨氏欲奔河东，至乾元被华州兵获", "start_year": 894, "end_year": 894, "time_original": "阆州突围后、894年八月献俘前", "dynasty": "唐", "description": "杨复恭、杨守亮、杨守信打算从商山逃往河东，至乾元遇华州军，被俘。", "phases": [], "location_name": "商山、乾元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5c7e9065-1696-5300-9987-da7e84bc4fa6"}, {"title": "韩建献杨复恭等，三人斩于独柳", "start_year": 894, "end_year": 894, "time_original": "894年八月", "dynasty": "唐", "description": "韩建将杨复恭、杨守亮、杨守信献到朝廷，三人被斩于独柳。", "phases": [], "location_name": "阙下、独柳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3e0fa830-4fc7-5903-a32e-390a4e315c64"}, {"title": "李茂贞献杨复恭给守亮的旧书", "start_year": 894, "end_year": 894, "time_original": "894年八月条；呈献确日未载", "dynasty": "唐", "description": "李茂贞献杨复恭曾写给杨守亮的书信。信中诉说自己致仕遭遇，令大侄积粟训兵勿贡献，并称自己扶立寿王却被废斥，骂皇帝为负心门生天子。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ad44c0b2-7ecb-58bb-bff9-fd7d95199016"}, {"title": "康君立到晋阳谒李克用", "start_year": 894, "end_year": 894, "time_original": "894年八月条；己未宴前", "dynasty": "唐", "description": "昭义节度使康君立到晋阳拜见李克用。", "phases": [], "location_name": "晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "088d0fa2-9e38-5f49-b276-d2ba03586a4c"}, {"title": "李克用宴饮念存孝，斫康君立并囚", "start_year": 894, "end_year": 894, "time_original": "894年八月己未", "dynasty": "唐", "description": "李克用同诸将饮酒博戏，谈到李存孝流泪。素与李存信友善的康君立说了一句忤意的话，李克用拔剑砍他，将其囚于马步司。", "phases": [], "location_name": "晋阳、马步司", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "664def4c-0fa7-54b6-aa59-f318e5133a26"}, {"title": "九月朔出康君立，已死", "start_year": 894, "end_year": 894, "time_original": "894年九月庚申朔；实际死亡在此之前", "dynasty": "唐", "description": "九月庚申初一将康君立从囚所移出时，康已死亡。", "phases": [], "location_name": "马步司", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "252ed1db-2108-5475-91d0-45b9b6cc157c"}, {"title": "李克用表云州刺史为昭义留后", "start_year": 894, "end_year": 894, "time_original": "894年九月条；具体日未载", "dynasty": "唐", "description": "李克用表请云州刺史薛志诚为昭义留后；结合旧史同任接替康君立段，暂对应既有薛志勤。", "phases": [], "location_name": "云州、昭义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c5467cf0-3eb9-52a6-ba37-21d9f14358aa"}, {"title": "昭宗封祤禊禋祎四皇子为王", "start_year": 894, "end_year": 894, "time_original": "894年冬十月丁酉", "dynasty": "唐", "description": "朝廷封皇子李祤为棣王、李禊为虔王、李禋为沂王、李祎为遂王。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d9c21c42-e98d-5f32-8c39-14ff34b3e768"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

